	sections = {
		{
			title = "Summary",
			text = [=[Above the {link:undercity}Undercity{/link} lie the broken streets of {link:lordaeron}Lordaeron{/link}'s {link:capital-city}Capital City{/link}. The {link:forsaken}Forsaken{/link} hold the courtyard before their gates, but beyond it much of the old city is still in the hands of the {link:scourge}Scourge{/link}. Mindless dead walk the alleys, great spiders nest in the ruins, and abominations stitched from the fallen guard the squares. Of late an unholy fog has crept over the streets and the old graveyard. The Forsaken have gone up to take their city back.]=],
		},
		{
			title = "Origins",
			text = [=[This was the capital of {link:lordaeron}Lordaeron{/link} until the day Prince {link:arthas-menethil}Arthas Menethil{/link} came home and murdered his father. The {link:scourge}Scourge{/link} sacked the city and slaughtered its people, and those who fell rose again to serve the Lich King. When the {link:forsaken}Forsaken{/link} broke free, they claimed the ruins and went below to build the {link:undercity}Undercity{/link}. They did not have the strength to clear the whole of the ruined city above them. Not long ago the necropolis {red:naxxramas}Naxxramas{/red} came against the city, and the fighting raged across these same streets. What the Scourge left behind has never been cleared away.]=],
		},
		{
			title = "The Present Day",
			text = [=[The {link:forsaken}Forsaken{/link} fight for their old streets one square at a time. They are losing soldiers they cannot replace, for decaying flesh does not heal. The Deathguard have learned that the fog is the work of a necromancer named {link:rath-mael}Rath'mael{/link}, a new power in the {link:scourge}Scourge{/link}'s ranks. He seems to be preparing another attack. The apothecaries of the {link:undercity}Undercity{/link} want samples of the ruins' venomous beasts, and the paladins of the Forsaken want the limbs of the fallen, so that their people can be mended.]=],
		},
		{
			title = "Within the Ruins",
			text = [=[• {b}King's Alley.{/b} Near the entrance, where a great spider hunts with her brood.
• {b}Market Street.{/b} An open square of the old city, where the dead gather in waves.
• {b}The {link:lordaeron-graveyard}Lordaeron Graveyard{/link}.{/b} The burial ground of the capital, now wrapped in fog.
• {b}The Lordamere Overlook.{/b} Deep in the ruins, where {link:rath-mael}Rath'mael{/link} works his magic.]=],
		},
		{
			title = "Relics of the Dead",
			text = [=[The ruins are full of what the living left behind. Soldiers' insignia lie in the rubble, still waiting for next of kin. Crests of the old kingdom turn up among the stones, and both the {link:forsaken}Forsaken{/link} and the people of {link:stormwind-city}Stormwind{/link} want them for their history. In the graveyard lies the last letter of a Forsaken named Edward Heartweaver. He came here every week to search for the body of his son, lost when {link:arthas-menethil}Arthas{/link} razed the city. He did not come back. His son, it turned out, had lived. He was carried to an orphanage in Stormwind, and he has since been adopted by a woman in {link:duskwood}Duskwood{/link}.]=],
		},
		{
			title = "Those Who Dwell Here",
			text = [=[The spider {link:witherfang}Witherfang{/link}, the abomination called {link:the-baron}the Baron{/link}, the Abandoned, the beast {link:viktor-the-vile}Viktor the Vile{/link}, the brute {link:bjork}Bjork{/link} and the necromancer {link:rath-mael}Rath'mael{/link} all haunt the ruins. The ghost of a captain of {link:lordaeron}Lordaeron{/link} is sometimes seen among them. An {link:alliance}Alliance{/link} soldier named Captain Truman still keeps his post in the ruins, waiting for a master who charged into the fray some time ago and has not returned.]=],
		},
	},
})

